#!/usr/bin/env python3
"""
Eingliederungsplan (BLD53011-BBB)  -  Excel  ->  PDF

Usage:
    python eingliederungsplan_pdf.py daten.xlsx                # one PDF per row -> ./output
    python eingliederungsplan_pdf.py daten.xlsx -o pdfs
    python eingliederungsplan_pdf.py daten.xlsx -l other_logo.png   # optional other logo

The Mainfränkische Werkstätten logo is built into this script.

Install:
    pip install reportlab openpyxl

Excel: first sheet, one row per participant, headers in row 1 (case-insensitive).
    Name | Vorname | Geburtsdatum | Kostenträger | Eingangsverfahren von |
    Eingangsverfahren bis | Datum | Diagnosen | Kompetenzanalyse |
    Hemmende Faktoren | Ziele | Bereich 1 | Bereich 2 | Bereich 3 |
    Bildungsbegleiter | Betriebliche Erprobung | Fahrdienst | ÖPNV | Sonstiges |
    BBB von | BBB bis

 - "Name" may also contain "Nachname, Vorname" (then leave Vorname empty).
 - Kostenträger: Bezirk Unterfranken / Agentur für Arbeit / DRV Nordbayern /
   DRV Bund / Andere Kostenträger (several allowed, separated by ; or ,)
 - Diagnosen, Kompetenzanalyse, Hemmende Faktoren, Ziele, Sonstiges: one bullet
   point per line in the cell (Alt+Enter) or separated by ";"
 - Betriebliche Erprobung, Fahrdienst, ÖPNV: Ja / Nein (blank = nothing ticked)
"""
import argparse
import datetime as dt
import os
import re

from openpyxl import load_workbook
from reportlab.lib.enums import TA_JUSTIFY
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle
from reportlab.pdfbase.pdfmetrics import stringWidth
from reportlab.pdfgen import canvas
from reportlab.platypus import Paragraph

PW, PH = A4
K = 72.0 / 110.0              # all coordinates below are pixels of a 110-dpi render


def X(px):
    return px * K


def Y(py):
    return PH - py * K


F, FB, FI = "Helvetica", "Helvetica-Bold", "Helvetica-Oblique"
GREY = 0.65
BAR_R = 796                    # right edge of the grey section bars
BAR_H = 22.5
BOTTOM_LIMIT = 1120            # content must stay above this (footer line at 1170)

KOSTENTRAEGER = ["Bezirk Unterfranken", "Agentur für Arbeit", "DRV Nordbayern",
                 "DRV Bund", "Andere Kostenträger"]

