def logo_reader(path=None):
    import base64, io
    from reportlab.lib.utils import ImageReader
    if path and os.path.exists(path):
        return ImageReader(path)
    return ImageReader(io.BytesIO(base64.b64decode("".join(LOGO_B64))))


# ------------------------------------------------------------------ helpers
def norm(s):
    return re.sub(r"[\s_]+", " ", str(s)).strip().lower()


def fmt_date(v):
    if v in (None, ""):
        return ""
    if isinstance(v, (dt.datetime, dt.date)):
        return v.strftime("%d.%m.%Y")
    return str(v).strip()


def items(v):
    if v in (None, ""):
        return []
    out = []
    for part in re.split(r"[\n;]+", str(v)):
        part = re.sub(r"^\s*[-•▪*–]\s*", "", part).strip()
        if part:
            out.append(part)
    return out


def yesno(v):
    s = norm(v) if v not in (None, "") else ""
    if s in ("ja", "j", "x", "yes", "true", "1", "wahr"):
        return "ja"
    if s in ("nein", "n", "no", "false", "0", "falsch"):
        return "nein"
    return None


def wrap(s, font, size, maxw):
    lines, cur = [], ""
    for w in s.split():
        t = (cur + " " + w).strip()
        if stringWidth(t, font, size) <= maxw or not cur:
            cur = t
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines or [""]


def fit(s, font, size, maxw, minsize=6):
    while size > minsize and stringWidth(s, font, size) > maxw:
        size -= 0.25
    return size


# ------------------------------------------------------------------ drawing
class Doc:
    def __init__(self, path, logo):
        self.c = canvas.Canvas(path, pagesize=A4)
        self.c.setTitle("Eingliederungsplan")
        self.logo = logo
        self.page = 0
        self.y = 0
        self.new_page(first=True)

    # --- primitives (110-dpi pixel coordinates)
    def line(self, x1, y1, x2, y2, w=0.8):
        self.c.setLineWidth(w)
        self.c.line(X(x1), Y(y1), X(x2), Y(y2))

    def rect(self, x1, y1, x2, y2, fill=None, w=0.8):
        c = self.c
        c.setLineWidth(w)
        if fill is not None:
            c.setFillGray(fill)
        c.rect(X(x1), Y(y2), X(x2) - X(x1), Y(y1) - Y(y2), stroke=1,
               fill=0 if fill is None else 1)
        c.setFillGray(0)

    def text(self, s, x, yc, size=11, font=F, align="left"):
        self.c.setFont(font, size)
        yb = Y(yc) - size * 0.35
        {"left": self.c.drawString, "center": self.c.drawCentredString,
         "right": self.c.drawRightString}[align](X(x), yb, s)

    # --- pages
    def new_page(self, first=False):
        if not first:
            self.c.showPage()
        self.page += 1
        self.text("Berufsbildungsbereich", 108, 56, 14)
        self.text("Eingliederungsplan", 108, 81, 12, FB)
        self.c.drawImage(logo_reader(self.logo), X(596), Y(103), X(847) - X(596),
                         Y(30) - Y(103), preserveAspectRatio=True, anchor="ne")
        self.line(108, 111, 449, 111, 1.7)
        self.line(449, 111.5, 843, 111.5, 1.0)
        self.line(99, 1170, 810, 1170, 2.0)
        self.text("04.01.2024 / MN", 108, 1180, 8)
        self.text("BLD53011-BBB-Eingliederungsplan", 342, 1178, 10, FI)
        self.text(f"Seite {self.page}", 804, 1179, 8, F, "right")
        self.y = 140

    def ensure(self, h):
        if self.y + h > BOTTOM_LIMIT:
            self.new_page()
            self.y = 170

    def bar(self, title, left=100, tx=108):
        self.ensure(BAR_H + 26 + 18)
        self.rect(left, self.y, BAR_R, self.y + BAR_H, fill=GREY)
        self.text(title, tx, self.y + BAR_H / 2 + 0.5, 12, FB)
        self.y += BAR_H

    def bullets(self, lst, kind="sq", left_x=152):
        lst = lst or [""]
        self.y += 26                       # centre of the first bullet line
        maxw = X(BAR_R - 8) - X(left_x)
        for ii, it in enumerate(lst):
            lines = wrap(it, F, 11, maxw)
            for li, ln in enumerate(lines):
                self.ensure(18)
                if li == 0:
                    self.c.setFillGray(0)
                    if kind == "sq":
                        r = 2.2
                        self.c.rect(X(133) - r, Y(self.y) - r, 2 * r, 2 * r, stroke=0, fill=1)
                    else:
                        self.c.circle(X(138), Y(self.y), 3, stroke=0, fill=1)
                self.text(ln, left_x, self.y, 11)
                last = ii == len(lst) - 1 and li == len(lines) - 1
                if not last:
                    self.y += 19 if li < len(lines) - 1 else 22
        self.y += 12                       # up to the top of whatever follows

    def section(self, title, lst, kind="sq", left=100, tx=108):
        self.bar(title, left, tx)
        self.bullets(lst, kind)

    def checkbox(self, x, yc, w, h, checked):
        self.c.setLineWidth(0.8)
        self.c.roundRect(X(x), Y(yc) - h * K / 2, w * K, h * K, 1.6, stroke=1, fill=0)
        if checked:
            self.c.setLineWidth(1.5)
            x0, x1 = X(x) + 3.2, X(x + w) - 3.2
            y0, y1 = Y(yc) - h * K / 2 + 3.2, Y(yc) + h * K / 2 - 3.2
            self.c.line(x0, y0, x1, y1)
            self.c.line(x0, y1, x1, y0)

    def save(self):
        self.c.showPage()
        self.c.save()


# ------------------------------------------------------------------ the form
def build(d, out, logo=None):
    D = Doc(out, logo)
    c = D.c

    # ---- page 1: Kostenträger box + address
    top, rh = 193, 18.6
    for i, name in enumerate(KOSTENTRAEGER):
        y1 = top + i * rh
        D.rect(108, y1, 301, y1 + rh)
        D.line(135, y1, 135, y1 + rh)
        D.text(name, 144, y1 + rh / 2 + 0.5, 10)
        if norm(name) in d["kosten"]:
            D.text("X", 121.5, y1 + rh / 2 + 0.5, 10, FB, "center")
    for s, yc, f in [("Telefon 09 31 / 2 00 22 – 0", 194, F),
                     ("Telefax 09 31 / 2 00 22 25", 209, F),
                     ("Ohmstraße 13, 97076 Würzburg", 224, FB),
                     ("e-mail: info@mfw-gmbh.com", 253, F),
                     ("www.mainfraenkische-werkstaetten.de", 267, F)]:
        D.text(s, 540, yc, 8, f)

    D.text("Eingliederungsplan", 240, 382, 16.2, FB)
    D.text("Würzburg,", 580, 384, 12.5)
    D.text(d["datum"], 680, 384, 11)

    D.text("Name, Vorname:", 108, 433, 11)
    D.text(d["name"], 250, 433, 11)
    D.text("Geb.-Datum:", 108, 464, 11)
    D.text(d["geb"], 250, 464, 11)
    D.text("Dauer Eingangsverfahren:", 108, 494, 11)
    D.text(d["ev_von"], 312, 494, 11)
    D.text("bis", 411, 494, 11, FB)
    D.text(d["ev_bis"], 450, 494, 11)

    D.y = 532
    D.section("Diagnosen", d["diagnosen"])
    D.section("Kompetenzanalyse", d["kompetenz"])
    D.section("Hemmende Faktoren", d["hemmend"])
    D.y += 22
    D.ensure(20)
    D.text("Er/Sie gehört eindeutig zum Personenkreis §53 SGB XII.", 108, D.y, 11)

    # ---- page 2: Förderplan (always starts on a new page)
    D.new_page()
    D.text("Förderziele – FÖRDERPLAN", 455, 184, 16, FB, "center")
    D.y = 226
    D.section("Ziele:", d["ziele"], left=95, tx=103)
    D.y += 47

    # Bereich table
    D.ensure(86 + 31 + 20)
    t = D.y
    D.rect(99, t, 135, t + 21, fill=GREY)
    D.rect(135, t, 570, t + 21, fill=GREY)
    D.text("Bereich", 144, t + 10.8, 11, FB)
    for i in range(3):
        y1 = t + 21 + 21.7 * i
        D.rect(99, y1, 135, y1 + 21.7)
        D.rect(135, y1, 570, y1 + 21.7)
        D.text(str(i + 1), 117, y1 + 11.4, 11, FB, "center")
        s = d["bereich"][i]
        if s:
            D.text(s, 144, y1 + 11.4, fit(s, F, 11, X(570 - 150)))
    D.y = t + 86 + 31

    D.text("Bildungsbegleiter:", 108, D.y, 11, FB)
    D.text(d["begleiter"], 270, D.y, 11)
    D.y += 68
    D.ensure(240)

    def tick(val, xja, xnein, w, h, yc):
        D.checkbox(xja, yc, w, h, val == "ja")
        D.checkbox(xnein, yc, w, h, val == "nein")

    # Betriebliche Erprobung (two-line label)
    D.text("Betriebliche Erprobung im kommenden", 108, D.y - 9.5, 11, FB)
    D.text("Jahr:", 108, D.y + 9.5, 11, FB)
    tick(d["erprobung"], 449, 558, 28, 20, D.y)
    D.text("Ja", 487, D.y, 11, FB)
    D.text("Nein", 596, D.y, 11, FB)
    D.y += 69
    D.text("Fahrdienst:", 108, D.y, 12, FB)
    tick(d["fahrdienst"], 466, 557, 23, 23, D.y)
    D.text("Ja", 497, D.y, 12, FB)
    D.text("Nein", 592, D.y, 12, FB)
    D.y += 51
    D.text("Öffentlicher Personennahverkehr:", 108, D.y, 12, FB)
    tick(d["oepnv"], 466, 557, 23, 23, D.y)
    D.text("Ja", 497, D.y, 12, FB)
    D.text("Nein", 592, D.y, 12, FB)
    D.y += 90

    D.section("Sonstiges:", d["sonstiges"], kind="round")
    D.y += 36

    # closing paragraph
    sp = "&nbsp;" * 9
    von, bis = d["bbb_von"] or sp, d["bbb_bis"] or sp
    style = ParagraphStyle("p", fontName=F, fontSize=11, leading=12.7, alignment=TA_JUSTIFY)
    para = Paragraph(
        "Die Leistungsfähigkeit&nbsp;&nbsp;kann durch den Berufsbildungsbereich noch wesentlich "
        "gesteigert werden. Dieser Eingliederungsplan muss ggf. angepasst oder erweitert "
        f"werden. Er/Sie nimmt vom {von} bis {bis} am&nbsp;&nbsp;1. Jahr des "
        "Berufsbildungsbereiches teil.", style)
    w = X(800 - 108)
    _, h = para.wrap(w, 300)
    D.ensure(h / K + 190)
    para.drawOn(c, X(108), Y(D.y - 10) - h)
    D.y += h / K + 101

    # signatures
    D.line(117, D.y, 428, D.y, 0.8)
    D.line(471, D.y, 781, D.y, 0.8)
    D.text("Fachkraft Arbeits- und Berufsförderung EV", 276, D.y + 16, 9, F, "center")
    D.text("Leitung Fachbereich Bildung", 628, D.y + 16, 9, F, "center")
    D.save()


# ------------------------------------------------------------------ Excel
ALIASES = {
    "name": ["name", "name, vorname", "nachname"],
    "vorname": ["vorname"],
    "geb": ["geburtsdatum", "geb.-datum", "geb datum", "geburtstag"],
    "kosten": ["kostenträger", "kostentraeger"],
    "ev_von": ["eingangsverfahren von", "ev von", "dauer eingangsverfahren von"],
    "ev_bis": ["eingangsverfahren bis", "ev bis", "dauer eingangsverfahren bis"],
    "datum": ["datum"],
    "diagnosen": ["diagnosen"],
    "kompetenz": ["kompetenzanalyse"],
    "hemmend": ["hemmende faktoren"],
    "ziele": ["ziele"],
    "b1": ["bereich 1", "bereich1"],
    "b2": ["bereich 2", "bereich2"],
    "b3": ["bereich 3", "bereich3"],
    "begleiter": ["bildungsbegleiter"],
    "erprobung": ["betriebliche erprobung", "betriebliche erprobung im kommenden jahr"],
    "fahrdienst": ["fahrdienst"],
    "oepnv": ["öpnv", "oepnv", "öffentlicher personennahverkehr"],
    "sonstiges": ["sonstiges"],
    "bbb_von": ["bbb von", "teilnahme von"],
    "bbb_bis": ["bbb bis", "teilnahme bis"],
}


def read_rows(path):
    ws = load_workbook(path, data_only=True).worksheets[0]
    rows = list(ws.iter_rows(values_only=True))
    heads = [norm(h) if h is not None else "" for h in rows[0]]
    for r in rows[1:]:
        if not any(v not in (None, "") for v in r):
            continue
        rec = dict(zip(heads, r))

        def g(key):
            for a in ALIASES[key]:
                v = rec.get(norm(a))
                if v not in (None, ""):
                    return v
            return None

        name = str(g("name") or "").strip()
        if g("vorname"):
            name = f"{name}, {str(g('vorname')).strip()}" if name else str(g("vorname"))
        kosten = {norm(k) for k in re.split(r"[;,]", str(g("kosten") or "")) if k.strip()}
        yield {
            "name": name, "geb": fmt_date(g("geb")), "kosten": kosten,
            "ev_von": fmt_date(g("ev_von")), "ev_bis": fmt_date(g("ev_bis")),
            "datum": fmt_date(g("datum")),
            "diagnosen": items(g("diagnosen")), "kompetenz": items(g("kompetenz")),
            "hemmend": items(g("hemmend")), "ziele": items(g("ziele")),
            "bereich": [str(g(k) or "") for k in ("b1", "b2", "b3")],
            "begleiter": str(g("begleiter") or ""),
            "erprobung": yesno(g("erprobung")), "fahrdienst": yesno(g("fahrdienst")),
            "oepnv": yesno(g("oepnv")), "sonstiges": items(g("sonstiges")),
            "bbb_von": fmt_date(g("bbb_von")), "bbb_bis": fmt_date(g("bbb_bis")),
        }


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("excel")
    ap.add_argument("-o", "--out", default="output")
    ap.add_argument("-l", "--logo", default=None,
                    help="optional: use another logo image (default logo is built in)")
    a = ap.parse_args()
    os.makedirs(a.out, exist_ok=True)
    n = 0
    for d in read_rows(a.excel):
        safe = re.sub(r"[^\w\-]+", "_", d["name"]).strip("_") or f"teilnehmer_{n + 1}"
        out = os.path.join(a.out, f"Eingliederungsplan_{safe}.pdf")
        build(d, out, a.logo)
        print("written", out)
        n += 1
    print(f"{n} PDF(s) created")


if __name__ == "__main__":
    main()
